<?php defined('BASEPATH') or exit('No direct script access allowed');$px=$discussion_extras??null;if(!$px)return;$pxEsc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$pxUrl=$url.'?operation_kind=projects&resource_id='.$discussion_project;$pxHidden=function(string $action,array $s,array $extra=[])use($pxEsc,$portal_csrf,$discussion_project){foreach(['action'=>$action,'portal_csrf'=>$portal_csrf,'project_id'=>$discussion_project,'project_revision'=>$s['project_revision']??1,'discussion_collection_revision'=>$s['collection_revision']??0,'discussion_id'=>$s['discussion_id'],'discussion_revision'=>$s['discussion_revision']??1,'discussion_post_id'=>$s['post_id'],'discussion_post_revision'=>$s['content_revision']??1,'request_key'=>bin2hex(random_bytes(32))]+$extra as $field=>$value)echo '<input type="hidden" name="'.$pxEsc($field).'" value="'.$pxEsc($value).'">';}; ?>
<section id="portal-discussion-subresources" style="overflow-wrap:anywhere"><h3>Seus comentários e anexos</h3><p>Você pode alterar seus próprios comentários enquanto a conversa estiver aberta. Cada alteração guarda a versão anterior e volta a ficar privada para você e a equipe; uma publicação anterior não publica o texto alterado. Anexos novos também são privados para você e a equipe. Excluir um comentário com respostas não é permitido.</p>
<?php if($px['change_receipt']){$r=$px['change_receipt']; ?><article id="portal-discussion-change-result"><h4><?= $r['receipt']['operation']==='delete'?'Comentário excluído da conversa':'Alteração registrada'; ?></h4><p>Revisão <?= (int)$r['receipt']['revision']; ?> · <?= $pxEsc($r['receipt']['editor_name']); ?></p><?php if($r['receipt']['body']!==null){ ?><p style="white-space:pre-wrap"><?= $pxEsc($r['receipt']['body']); ?></p><a href="<?= $pxEsc($pxUrl.'&discussion_parent='.$r['discussion_id'].'&discussion_post='.$r['post_id']); ?>">Retomar seu comentário atual</a><?php }else{ ?><p>O histórico foi preservado. A exclusão não permite recuperar ou republicar o comentário por este formulário.</p><?php } ?></article><?php } ?>
<?php if($px['file_receipt']){$r=$px['file_receipt']; ?><article id="portal-discussion-file-result"><h4>Resultado privado do anexo</h4><p><?= isset($r['receipt']['filename'])?$pxEsc($r['receipt']['filename']):'Anexo ocultado'; ?> · <?= $r['active']?'Disponível para você e a equipe':'Oculto; download indisponível'; ?></p><a href="<?= $pxEsc($pxUrl.'&discussion_parent='.$r['discussion_id'].'&discussion_post='.$r['post_id']); ?>">Retomar seu comentário e anexos</a></article><?php } ?>
<?php if($px['workspace']){$w=$px['workspace']; ?><article id="portal-discussion-own-comment"><h4>Seu comentário atual · revisão <?= (int)$w['content_revision']; ?></h4><p><?= $pxEsc($w['author_name']); ?></p><?php if($w['can_change']){echo form_open($url,['id'=>'portal-discussion-edit']);$pxHidden('project_discussion_edit',$w); ?><label for="portal-discussion-edit-body">Texto da nova versão privada</label><textarea id="portal-discussion-edit-body" rows="5" style="display:block;width:100%;box-sizing:border-box" name="discussion_body" maxlength="8000" required><?= $pxEsc($w['body']); ?></textarea><button type="submit">Salvar nova versão privada</button><?= form_close(); ?><?php }if($w['can_delete']){echo form_open($url,['id'=>'portal-discussion-delete']);$pxHidden('project_discussion_delete',$w); ?><button type="submit">Excluir meu comentário sem respostas</button><?= form_close(); ?><?php }else{ ?><p>Este comentário possui respostas; a exclusão não está disponível.</p><?php }if(!$w['can_change']){ ?><p style="white-space:pre-wrap"><?= $pxEsc($w['body']); ?></p><p>A edição está indisponível: a conversa ou o projeto foi encerrado, ou a mensagem atingiu100 versões. A exclusão sem respostas permanece disponível enquanto a conversa estiver aberta.</p><?php } ?></article><?php } ?>
<?php foreach($px['files'] as $list){ ?><article class="portal-discussion-file-list" data-post="<?= (int)$list['post_id']; ?>"><h4>Anexos disponíveis do comentário #<?= (int)$list['post_id']; ?></h4><?php foreach($list['files'] as $f){echo form_open($url,['class'=>'portal-discussion-file-download']);$pxHidden('project_discussion_file_download',$list,['file_key'=>$f['file_key']]); ?><span><?= $pxEsc($f['filename']); ?> · <?= (int)$f['byte_size']; ?> bytes · <?= $f['audience']==='private'?'Privado para o autor e a equipe':($f['publication_current']?'Compartilhamento explícito vigente':'Privado para o autor e a equipe; compartilhamento anterior depende de nova publicação'); ?></span><button type="submit">Baixar anexo</button><?= form_close(); ?><?php if($f['can_hide']){echo form_open($url,['class'=>'portal-discussion-file-hide']);$pxHidden('project_discussion_file_hide',$list,['file_key'=>$f['file_key']]); ?><button type="submit">Ocultar meu anexo</button><?= form_close(); ?><?php }}if($list['can_upload']){echo form_open_multipart($url,['class'=>'portal-discussion-file-upload']);$pxHidden('project_discussion_file_upload',$list); ?><p>O anexo será privado para você e a equipe. PDF até2 MiB; PNG/JPEG até512 KiB e1600 pixels; limite total de20 anexos/20 MiB por conversa, incluindo ocultos.</p><label>Arquivo do seu comentário<input type="file" name="discussion_file" accept="application/pdf,image/png,image/jpeg" required></label><button type="submit">Anexar arquivo privado ao comentário</button><?= form_close(); ?><?php } ?></article><?php } ?></section>
